class SpaceParticle {
  constructor(x, y, angle) {
    this.x = x + random(-3, 3);
    this.y = y + random(-3, 3);
    this.angle = angle;
    this.speed = random(0.05, 0.1);

  }
  update() {

    this.angle+=map(dist(this.x,this.y,0,0), 0, width, .25, .5);
    this.angle -= 0.1
    this.angle %= 360;
    this.show();
  }
  show() {
    //fill(255, 204 - dist(this.x, this.y, 0, 0), 255, 80);

    fill(255, 154, 255, 50);
    push()
    rotate(this.angle);
    ellipse(this.x, this.y, 10, 10);
    pop()
  }
}
const directions = [];
var particles = [];

function setup() {
  createCanvas(windowWidth, windowHeight);
  angleMode(DEGREES)
  // directions[0] = createVector(0, 1);
  // directions[1] = createVector(0, -1);
  // directions[2] = createVector(1, 0);
  // directions[3] = createVector(-1, 0);
  for (i = 360; i > 0; i -= 360 / 4) {
    directions.push(p5.Vector.fromAngle(radians(i)))
  }
  console.log(directions.length)
  noStroke()
  for (i = 0; i < 360 * 2; i++) {
    let dir = directions[i % directions.length];
    particles.push(new SpaceParticle(dir.x * (i / 2), dir.y * (i / 2), i));


    //This way for better looking
    // for (let j = 0; j < 4; j++) {
    //   let dir = directions[j]
    //   particles.push(new SpaceParticle(dir.x * i, dir.y * i, i));
    // }
  }
  stars = [];
  starAngle = 0;
  for (i = 0; i < 100; i++) {
    stars.push(createVector(random(-width / 2, width / 2), random(-height / 2, height / 2)))
  }
}

function draw() {
  background(0, 50);

  translate(width / 2, height / 2);

  for (let particle of particles) {
    push()
    shearX(50);
    particle.update();
    pop()
  }
      starAngle += .2;
    starAngle %= 360;
  shearX(50)
  for (let star of stars) {
    fill(255);
    push()
    rotate(starAngle)
    ellipse(star.x, star.y, 2, 2)
    pop()
  }
}

